SELECT p.sku, p.path, p.brand, p.series, p.model, p.name, json_extract(p.properties,'$.storage_type') AS storage_type FROM products p WHERE p.brand='Festool' AND p.series LIKE '%Festool Stackable SYS 3JJ-9LM Tool Box and Bag%' AND p.model='3JJ-9LM' AND p.name='Tool Box and Bag' AND lower(replace(json_extract(p.properties,'$.storage_type'),' ','')) IN ('partscase','parts case') LIMIT 10; 
SELECT s.store_id, s.name, s.city, s.path FROM stores s WHERE s.city='Graz' ORDER BY s.store_id; 
SELECT s.store_id, COALESCE(i.available_today,0) AS available_today FROM stores s LEFT JOIN inventory i ON i.store_id=s.store_id AND i.sku IN (SELECT p2.sku FROM products p2 WHERE p2.brand='Festool' AND p2.series LIKE '%Festool Stackable SYS 3JJ-9LM Tool Box and Bag%' AND p2.model='3JJ-9LM' AND p2.name='Tool Box and Bag' AND lower(replace(json_extract(p2.properties,'$.storage_type'),' ','')) IN ('partscase','parts case')) WHERE s.city='Graz' ORDER BY s.store_id;

SELECT pv.product_sku, pv.record_path, pv.brand, pv.series, pv.model, pv.product_name, json_extract(pv.properties,'$.storage_type') AS storage_type FROM product_variants pv WHERE pv.brand='Festool' AND pv.series LIKE '%Festool Stackable SYS 3JJ-9LM Tool Box and Bag%' AND pv.model='3JJ-9LM' AND pv.product_name LIKE '%Tool Box and Bag%' AND lower(replace(json_extract(pv.properties,'$.storage_type'),' ',''))='partscase' LIMIT 20;
SELECT s.store_id, s.record_path, s.store_name, s.city, COALESCE(si.available_today_quantity,0) AS available_today_quantity FROM stores s LEFT JOIN store_inventory si ON si.store_id=s.store_id AND si.product_sku IN (SELECT pv2.product_sku FROM product_variants pv2 WHERE pv2.brand='Festool' AND pv2.series LIKE '%Festool Stackable SYS 3JJ-9LM Tool Box and Bag%' AND pv2.model='3JJ-9LM' AND pv2.product_name LIKE '%Tool Box and Bag%' AND lower(replace(json_extract(pv2.properties,'$.storage_type'),' ',''))='partscase') WHERE s.city='Graz' ORDER BY s.store_id;
SELECT SUM(COALESCE(si.available_today_quantity,0)) AS qty_total FROM stores s LEFT JOIN store_inventory si ON si.store_id=s.store_id AND si.product_sku IN (SELECT pv2.product_sku FROM product_variants pv2 WHERE pv2.brand='Festool' AND pv2.series LIKE '%Festool Stackable SYS 3JJ-9LM Tool Box and Bag%' AND pv2.model='3JJ-9LM' AND pv2.product_name LIKE '%Tool Box and Bag%' AND lower(replace(json_extract(pv2.properties,'$.storage_type'),' ',''))='partscase') WHERE s.city='Graz';

